/* ------------------------------------------------------------------ */
/* Glass helpers                                                       */
/* ------------------------------------------------------------------ */
function hexToRgb(hex) {
  return {
    r: parseInt(hex.slice(1, 3), 16),
    g: parseInt(hex.slice(3, 5), 16),
    b: parseInt(hex.slice(5, 7), 16),
  };
}
function tint(hex, alpha) {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r},${g},${b},${alpha})`;
}
function glass({ alpha = 0.11, blur = 28, border = C.border, glow = null } = {}) {
  return {
    backgroundColor: `rgba(255,255,255,${alpha})`,
    backdropFilter: `blur(${blur}px) saturate(190%) brightness(1.06)`,
    WebkitBackdropFilter: `blur(${blur}px) saturate(190%) brightness(1.06)`,
    border: `1px solid ${border}`,
    boxShadow: glow
      ? `0 20px 50px -10px ${glow}, inset 0 1px 0 rgba(255,255,255,0.28), inset 0 -1px 0 rgba(0,0,0,0.15)`
      : '0 20px 50px -12px rgba(0,0,0,0.5), 0 6px 18px rgba(0,0,0,0.28), inset 0 1px 0 rgba(255,255,255,0.22), inset 0 -1px 0 rgba(0,0,0,0.12)',
  };
}
function glassTint(hex, alpha = 0.2, blur = 28) {
  return {
    backgroundColor: tint(hex, alpha),
    backdropFilter: `blur(${blur}px) saturate(200%) brightness(1.06)`,
    WebkitBackdropFilter: `blur(${blur}px) saturate(200%) brightness(1.06)`,
    border: `1px solid ${tint(hex, 0.4)}`,
    boxShadow: `0 20px 54px -10px ${tint(hex, 0.28)}, inset 0 1px 0 rgba(255,255,255,0.3), inset 0 -1px 0 rgba(0,0,0,0.12)`,
  };
}

