/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const emptyData = () => ({ subjects: [], exams: [], homework: [], sessions: [], aiPlans: [] });

function todayISO() {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d.toISOString().slice(0, 10);
}
function parseISO(s) {
  return new Date(s + 'T00:00:00');
}
function daysBetween(fromISO, toISO) {
  return Math.round((parseISO(toISO) - parseISO(fromISO)) / 86400000);
}
function addDays(iso, n) {
  const d = parseISO(iso);
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}
function formatThaiDate(iso) {
  const d = parseISO(iso);
  return `${d.getDate()} ${THAI_MONTHS[d.getMonth()]} ${d.getFullYear() + 543}`;
}
function dueLabel(iso) {
  const diff = daysBetween(todayISO(), iso);
  if (diff < 0) return { text: `เลยกำหนด ${Math.abs(diff)} วัน`, urgent: true };
  if (diff === 0) return { text: 'วันนี้', urgent: true };
  if (diff === 1) return { text: 'พรุ่งนี้', urgent: true };
  if (diff <= 3) return { text: `อีก ${diff} วัน`, urgent: true };
  return { text: `อีก ${diff} วัน`, urgent: false };
}
function getSubject(list, id) {
  return list.find((s) => s.id === id) || { id: null, name: 'ไม่ระบุวิชา', color: C.textMuted };
}
function generateStudyPlan(exam) {
  const today = todayISO();
  const totalDays = daysBetween(today, exam.date);
  if (totalDays <= 0) return [];
  const remaining = Math.max(exam.chapters - (exam.chaptersDone || 0), 0);
  if (remaining === 0) return [];
  let reviewDays = 0;
  if (totalDays >= 5) reviewDays = 2;
  else if (totalDays >= 2) reviewDays = 1;
  const readDays = Math.max(totalDays - reviewDays, 1);
  const perDay = Math.ceil(remaining / readDays);
  const plan = [];
  let cursor = (exam.chaptersDone || 0) + 1;
  let offset = 0;
  for (let i = 0; i < readDays && cursor <= exam.chapters; i++) {
    const start = cursor;
    const end = Math.min(cursor + perDay - 1, exam.chapters);
    const label = start === end ? `อ่านบทที่ ${start}` : `อ่านบทที่ ${start}-${end}`;
    plan.push({ date: addDays(today, offset), task: label });
    cursor = end + 1;
    offset++;
  }
  for (let i = 0; i < reviewDays; i++) {
    const label = i === reviewDays - 1 ? 'ทบทวนทั้งหมดก่อนสอบ' : 'ทำโจทย์ทบทวน';
    plan.push({ date: addDays(today, offset), task: label });
    offset++;
  }
  return plan;
}

