function Homework({ data, addHomework, toggleHomework, deleteHomework }) {
  const [showForm, setShowForm] = useState(false);
  const [filter, setFilter] = useState('pending');
  const [form, setForm] = useState({ title: '', subjectId: '', dueDate: '', priority: 'medium' });

  const inputStyle = { ...glass({ alpha: 0.10 }), color: C.text };

  function submit(e) {
    e.preventDefault();
    if (!form.title.trim() || !form.subjectId || !form.dueDate) return;
    addHomework({ ...form, title: form.title.trim() });
    setForm({ title: '', subjectId: '', dueDate: '', priority: 'medium' });
    setShowForm(false);
  }

  const filtered = data.homework
    .filter((h) => (filter === 'all' ? true : filter === 'pending' ? !h.done : h.done))
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate));

  return (
    <div className="space-y-5 pb-4">
      <div className="flex items-center justify-between">
        <div>
          <p className="font-body text-sm" style={{ color: C.textMuted }}>งานที่ต้องส่ง</p>
          <h1 className="font-display text-2xl mt-0.5" style={{ color: C.text }}>การบ้าน</h1>
        </div>
        <button
          aria-label="เพิ่มการบ้าน"
          onClick={() => setShowForm((v) => !v)}
          className="sm-btn sm-lift w-11 h-11 rounded-full flex items-center justify-center"
          style={glassTint(C.violet, 0.22, 20)}
        >
          <Plus size={18} style={{ color: C.text }} />
        </button>
      </div>

      {showForm && (
        <div className="sm-pop-anim p-4 rounded-2xl space-y-3" style={glass({ alpha: 0.12 })}>
          {data.subjects.length === 0 ? (
            <p className="font-body text-sm" style={{ color: C.textMuted }}>เพิ่มวิชาก่อนในหน้าวางแผน</p>
          ) : (
            <>
              <FormField label="ชื่องาน">
                <input
                  value={form.title}
                  onChange={(e) => setForm({ ...form, title: e.target.value })}
                  placeholder="เช่น แบบฝึกหัดบทที่ 5"
                  className="sm-input w-full px-3 py-2 rounded-xl font-body text-sm"
                  style={inputStyle}
                />
              </FormField>
              <FormField label="วิชา">
                <select
                  value={form.subjectId}
                  onChange={(e) => setForm({ ...form, subjectId: e.target.value })}
                  className="sm-input w-full px-3 py-2 rounded-xl font-body text-sm"
                  style={inputStyle}
                >
                  <option value="" style={{ color: '#111' }}>เลือกวิชา</option>
                  {data.subjects.map((s) => <option key={s.id} value={s.id} style={{ color: '#111' }}>{s.name}</option>)}
                </select>
              </FormField>
              <FormField label="วันส่ง">
                <input
                  type="date"
                  value={form.dueDate}
                  onChange={(e) => setForm({ ...form, dueDate: e.target.value })}
                  className="sm-input w-full px-3 py-2 rounded-xl font-body text-sm"
                  style={inputStyle}
                />
              </FormField>
              <FormField label="ความสำคัญ">
                <div className="flex gap-2">
                  {Object.entries(PRIORITY).map(([key, cfg]) => (
                    <button
                      type="button"
                      key={key}
                      onClick={() => setForm({ ...form, priority: key })}
                      className="sm-btn flex-1 py-1.5 rounded-xl font-body text-xs"
                      style={{
                        border: form.priority === key ? `1.5px solid ${cfg.color}` : `1px solid ${C.border}`,
                        color: form.priority === key ? cfg.color : C.textMuted,
                        backgroundColor: form.priority === key ? `${cfg.color}22` : 'transparent',
                      }}
                    >
                      {cfg.label}
                    </button>
                  ))}
                </div>
              </FormField>
              <button type="button" onClick={submit} className="sm-btn w-full py-2.5 rounded-xl font-body text-sm" style={{ backgroundColor: C.text, color: C.bgDeep }}>
                เพิ่มการบ้าน
              </button>
            </>
          )}
        </div>
      )}

      <div className="flex gap-2">
        {[['pending', 'ค้างอยู่'], ['done', 'เสร็จแล้ว'], ['all', 'ทั้งหมด']].map(([key, label]) => (
          <button
            key={key}
            onClick={() => setFilter(key)}
            className="sm-btn px-3 py-1.5 rounded-full font-body text-xs"
            style={
              filter === key
                ? { ...glassTint(C.sky, 0.24, 16), color: C.text }
                : { border: `1px solid ${C.border}`, color: C.textMuted }
            }
          >
            {label}
          </button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <EmptyRow text={filter === 'done' ? 'ยังไม่มีงานที่ทำเสร็จ' : 'ไม่มีงานในหมวดนี้'} />
      ) : (
        <div className="rounded-2xl px-4 divide-y" style={{ ...glass({ alpha: 0.10 }), borderColor: C.border }}>
          {filtered.map((h) => {
            const subj = getSubject(data.subjects, h.subjectId);
            const due = dueLabel(h.dueDate);
            const pr = PRIORITY[h.priority] || PRIORITY.medium;
            return (
              <div
                key={h.id}
                className="flex items-center gap-3 py-3 pl-3"
                style={{ borderLeft: `3px solid ${subj.color}`, borderColor: C.border, opacity: h.done ? 0.5 : 1 }}
              >
                <button
                  aria-label={h.done ? 'ทำเครื่องหมายว่ายังไม่เสร็จ' : 'ทำเครื่องหมายว่าทำเสร็จแล้ว'}
                  onClick={() => toggleHomework(h.id)}
                  className="sm-btn w-6 h-6 rounded-full flex items-center justify-center shrink-0"
                  style={{ border: `1.5px solid ${h.done ? C.mint : C.border}`, backgroundColor: h.done ? C.mint : 'transparent' }}
                >
                  {h.done && <Check size={13} color="#0A1410" />}
                </button>
                <div className="flex-1 min-w-0">
                  <p className="font-body text-sm truncate" style={{ color: C.text, textDecoration: h.done ? 'line-through' : 'none' }}>
                    {h.title}
                  </p>
                  <p className="font-body text-xs mt-0.5" style={{ color: C.textMuted }}>{subj.name} · {pr.label}</p>
                </div>
                {!h.done && (
                  <span
                    className="font-body text-xs px-2 py-1 rounded-full shrink-0"
                    style={due.urgent ? { color: '#fff', backgroundColor: C.coral } : { color: C.textMuted }}
                  >
                    {due.text}
                  </span>
                )}
                <button aria-label="ลบการบ้าน" onClick={() => deleteHomework(h.id)} className="sm-btn">
                  <Trash2 size={14} style={{ color: C.textMuted }} />
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Focus mode                                                           */
/* ------------------------------------------------------------------ */
function Focus({ data, logSession }) {
  const [presetIdx, setPresetIdx] = useState(0);
  const [subjectId, setSubjectId] = useState(data.subjects[0]?.id || '');
  const [mode, setMode] = useState('work');
  const [secondsLeft, setSecondsLeft] = useState(PRESETS[0].work * 60);
  const [running, setRunning] = useState(false);
  const intervalRef = useRef(null);

  useEffect(() => {
    if (!subjectId && data.subjects.length > 0) setSubjectId(data.subjects[0].id);
  }, [data.subjects]); // eslint-disable-line

  useEffect(() => {
    if (running) {
      intervalRef.current = setInterval(() => {
        setSecondsLeft((s) => {
          if (s <= 1) {
            handleComplete();
            return 0;
          }
          return s - 1;
        });
      }, 1000);
    }
    return () => clearInterval(intervalRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running, mode]);

  function handleComplete() {
    clearInterval(intervalRef.current);
    if (mode === 'work') {
      if (subjectId) logSession(subjectId, PRESETS[presetIdx].work);
      setMode('break');
      setSecondsLeft(PRESETS[presetIdx].brk * 60);
      setRunning(false);
    } else {
      setMode('work');
      setSecondsLeft(PRESETS[presetIdx].work * 60);
      setRunning(false);
    }
  }
  function reset() {
    setRunning(false);
    setMode('work');
    setSecondsLeft(PRESETS[presetIdx].work * 60);
  }
  function selectPreset(i) {
    setPresetIdx(i);
    setRunning(false);
    setMode('work');
    setSecondsLeft(PRESETS[i].work * 60);
  }

  const totalSeconds = (mode === 'work' ? PRESETS[presetIdx].work : PRESETS[presetIdx].brk) * 60;
  const pct = totalSeconds > 0 ? (1 - secondsLeft / totalSeconds) * 100 : 0;
  const mm = String(Math.floor(secondsLeft / 60)).padStart(2, '0');
  const ss = String(secondsLeft % 60).padStart(2, '0');

  const todayStr = todayISO();
  const todayMinutes = data.sessions.filter((s) => s.date === todayStr).reduce((sum, s) => sum + s.minutes, 0);
  const modeColor = mode === 'work' ? C.violet : C.mint;
  const inputStyle = { ...glass({ alpha: 0.10 }), color: C.text };

  return (
    <div className="space-y-6 pb-4">
      <div>
        <p className="font-body text-sm" style={{ color: C.textMuted }}>โฟกัสโหมด</p>
        <h1 className="font-display text-2xl mt-0.5" style={{ color: C.text }}>ตั้งเวลาอ่านหนังสือ</h1>
      </div>

      {running && (
        <div className="sm-floating-player sm-modal-anim md:hidden fixed bottom-20 left-3 right-3 z-30 px-4 py-3 flex items-center gap-3">
          <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ backgroundColor: tint(modeColor, 0.3) }}>
            <Timer size={16} style={{ color: C.text }} />
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-body text-xs truncate" style={{ color: C.textMuted }}>{mode === 'work' ? 'กำลังโฟกัส' : 'พักสายตา'}</p>
            <p className="font-num text-sm" style={{ color: C.text }}>{mm}:{ss}</p>
          </div>
          <button
            aria-label="พัก"
            onClick={() => setRunning((r) => !r)}
            className="sm-btn w-10 h-10 rounded-full flex items-center justify-center shrink-0"
            style={{ backgroundColor: C.text }}
          >
            <Pause size={16} style={{ color: C.bgDeep }} />
          </button>
        </div>
      )}

      {data.subjects.length === 0 ? (
        <EmptyRow text="เพิ่มวิชาก่อนในหน้าวางแผน เพื่อบันทึกเวลาอ่านแยกตามวิชา" />
      ) : (
        <>
          <div className="flex gap-2">
            {PRESETS.map((p, i) => (
              <button
                key={p.label}
                disabled={running}
                onClick={() => selectPreset(i)}
                className="sm-btn flex-1 py-2 rounded-2xl font-body text-xs"
                style={
                  presetIdx === i
                    ? { ...glassTint(C.violet, 0.24, 16), color: C.text, opacity: running ? 0.6 : 1 }
                    : { ...glass({ alpha: 0.12 }), color: C.textMuted, opacity: running ? 0.6 : 1 }
                }
              >
                {p.label}<br /><span className="font-num">{p.work}/{p.brk}</span>
              </button>
            ))}
          </div>

          <select
            value={subjectId}
            onChange={(e) => setSubjectId(e.target.value)}
            disabled={running}
            className="sm-input w-full px-3 py-2 rounded-xl font-body text-sm"
            style={{ ...inputStyle, opacity: running ? 0.6 : 1 }}
          >
            {data.subjects.map((s) => <option key={s.id} value={s.id} style={{ color: '#111' }}>{s.name}</option>)}
          </select>

          <div className="sm-lift rounded-3xl p-8 flex flex-col items-center" style={glassTint(modeColor, 0.14, 30)}>
            <p className="font-body text-xs" style={{ color: C.textMuted }}>{mode === 'work' ? 'กำลังอ่าน' : 'พักสายตา'}</p>
            <p className="font-num text-6xl mt-2" style={{ color: C.text }}>{mm}:{ss}</p>
            <div className="w-full mt-5">
              <ProgressBar value={pct} max={100} color={modeColor} />
            </div>
            <div className="flex items-center gap-3 mt-6">
              <button
                aria-label="รีเซ็ตเวลา"
                onClick={reset}
                className="sm-btn w-11 h-11 rounded-full flex items-center justify-center"
                style={{ border: `1px solid ${C.border}` }}
              >
                <RotateCcw size={17} style={{ color: C.text }} />
              </button>
              <button
                aria-label={running ? 'พัก' : 'เริ่ม'}
                onClick={() => setRunning((r) => !r)}
                className={`sm-btn w-16 h-16 rounded-full flex items-center justify-center ${running ? 'sm-pulse' : ''}`}
                style={{ backgroundColor: C.text }}
              >
                {running ? <Pause size={22} style={{ color: C.bgDeep }} /> : <Play size={22} style={{ color: C.bgDeep, marginLeft: 2 }} />}
              </button>
              <div className="w-11 h-11" />
            </div>
          </div>

          <div className="flex items-center justify-between px-1">
            <p className="font-body text-sm" style={{ color: C.textMuted }}>วันนี้อ่านไปแล้ว</p>
            <p className="font-num text-sm" style={{ color: C.text }}>{Math.floor(todayMinutes / 60)} ชม. {todayMinutes % 60} นาที</p>
          </div>
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Statistics                                                           */
/* ------------------------------------------------------------------ */
function Stats({ data, resetAll }) {
  const todayStr = todayISO();
  const last7 = Array.from({ length: 7 }, (_, i) => addDays(todayStr, -(6 - i)));
  const byDay = last7.map((date) => ({
    date,
    minutes: data.sessions.filter((s) => s.date === date).reduce((sum, s) => sum + s.minutes, 0),
  }));
  const weekTotal = byDay.reduce((sum, d) => sum + d.minutes, 0);
  const bySubject = {};
  data.sessions.filter((s) => last7.includes(s.date)).forEach((s) => {
    bySubject[s.subjectId] = (bySubject[s.subjectId] || 0) + s.minutes;
  });
  const subjectRows = Object.entries(bySubject)
    .map(([subjectId, minutes]) => ({ subject: getSubject(data.subjects, subjectId), minutes }))
    .sort((a, b) => b.minutes - a.minutes);
  const maxDay = Math.max(...byDay.map((d) => d.minutes), 1);
  const [confirmReset, setConfirmReset] = useState(false);

  function fmt(min) {
    return `${Math.floor(min / 60)} ชม. ${min % 60} น.`;
  }

  return (
    <div className="space-y-6 pb-4">
      <div>
        <p className="font-body text-sm" style={{ color: C.textMuted }}>สถิติการอ่านหนังสือ</p>
        <h1 className="font-display text-2xl mt-0.5" style={{ color: C.text }}>
          สัปดาห์นี้: <span className="font-num">{fmt(weekTotal)}</span>
        </h1>
      </div>

      <Section title="เวลาที่อ่านแต่ละวัน">
        <div className="rounded-2xl p-4" style={glass({ alpha: 0.10 })}>
          <div className="flex items-end gap-2 h-32 px-1">
            {byDay.map((d) => (
              <div key={d.date} className="flex-1 flex flex-col items-center gap-1.5 h-full justify-end">
                <div
                  className="w-full rounded-t-md transition-all duration-500"
                  style={{
                    height: `${Math.max((d.minutes / maxDay) * 100, 4)}%`,
                    backgroundColor: d.date === todayStr ? C.sky : 'rgba(255,255,255,0.16)',
                    boxShadow: d.date === todayStr ? `0 0 12px ${C.sky}88` : 'none',
                    minHeight: '4px',
                  }}
                />
                <span className="font-body" style={{ color: C.textMuted, fontSize: '11px' }}>
                  {THAI_WEEKDAYS_SHORT[parseISO(d.date).getDay()]}
                </span>
              </div>
            ))}
          </div>
        </div>
      </Section>

      <Section title="แยกตามวิชา (7 วันล่าสุด)">
        {subjectRows.length === 0 ? (
          <EmptyRow text="ยังไม่มีข้อมูลการอ่าน — เริ่มโหมดโฟกัสเพื่อบันทึกเวลา" />
        ) : (
          <div className="rounded-2xl p-4 space-y-3" style={glass({ alpha: 0.10 })}>
            {subjectRows.map((row) => (
              <div key={row.subject.id || row.subject.name}>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-body text-sm flex items-center gap-1.5" style={{ color: C.text }}>
                    <span className="w-2 h-2 rounded-full" style={{ backgroundColor: row.subject.color }} />
                    {row.subject.name}
                  </span>
                  <span className="font-num text-xs" style={{ color: C.textMuted }}>{fmt(row.minutes)}</span>
                </div>
                <ProgressBar value={row.minutes} max={weekTotal || 1} color={row.subject.color} />
              </div>
            ))}
          </div>
        )}
      </Section>

      <div className="pt-6" style={{ borderTop: `1px solid ${C.border}` }}>
        {!confirmReset ? (
          <button onClick={() => setConfirmReset(true)} className="sm-btn font-body text-xs" style={{ color: C.textMuted }}>
            รีเซ็ตข้อมูลทั้งหมด
          </button>
        ) : (
          <div className="flex items-center gap-3 flex-wrap">
            <p className="font-body text-xs" style={{ color: C.coral }}>ลบข้อมูลทั้งหมดถาวร ใช่ไหม?</p>
            <button
              onClick={() => { resetAll(); setConfirmReset(false); }}
              className="sm-btn font-body text-xs underline"
              style={{ color: C.coral }}
            >
              ยืนยัน
            </button>
            <button onClick={() => setConfirmReset(false)} className="sm-btn font-body text-xs" style={{ color: C.textMuted }}>
              ยกเลิก
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* AI Study Assistant                                                   */
/* ------------------------------------------------------------------ */
function AIAssistantPanel({ saveAIPlan, embedded }) {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [saved, setSaved] = useState(false);

  async function ask() {
    if (!input.trim()) return;
    setLoading(true);
    setError(null);
    setResult(null);
    setSaved(false);
    try {
      const system =
        `คุณคือผู้ช่วยวางแผนอ่านหนังสือสอบสำหรับนักเรียนไทย วันนี้คือ ${formatThaiDate(todayISO())} ` +
        `ตอบกลับเป็น JSON ล้วนๆ เท่านั้น ห้ามมีข้อความอื่นหรือ markdown code fence ` +
        `โครงสร้างต้องเป็น: {"subject":"ชื่อวิชา","totalDays":number,"plan":[{"date_label":"วันนี้ หรือ พรุ่งนี้ หรือ วันที่ระบุ","task":"สิ่งที่ต้องทำแบบสั้นกระชับ"}]} ` +
        `ให้แบ่งเนื้อหาตามจำนวนวันที่เหลืออย่างสมเหตุสมผล และเผื่อ 1-2 วันสุดท้ายไว้สำหรับทบทวนหรือทำโจทย์ ตอบเป็นภาษาไทยทั้งหมด`;
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-6',
          max_tokens: 1000,
          system,
          messages: [{ role: 'user', content: input.trim() }],
        }),
      });
      const json = await res.json();
      const textBlock = (json.content || []).map((b) => b.text || '').join('');
      const clean = textBlock.replace(/```json|```/g, '').trim();
      const parsed = JSON.parse(clean);
      setResult(parsed);
    } catch (e) {
      console.error(e);
      setError('ขอโทษ ผู้ช่วย AI ตอบไม่สำเร็จ ลองพิมพ์ใหม่อีกครั้ง');
    } finally {
      setLoading(false);
    }
  }

  function handleSave() {
    if (!result) return;
    saveAIPlan(result);
    setSaved(true);
  }

  return (
    <div className="space-y-4">
      {!embedded && (
        <h3 className="font-display text-lg flex items-center gap-2" style={{ color: C.text }}>
          <Sparkles size={18} style={{ color: C.violet }} /> ผู้ช่วย AI
        </h3>
      )}
      <p className="font-body text-sm" style={{ color: C.textMuted }}>
        บอกสถานการณ์การอ่านหนังสือ เดี๋ยว StudyMate ช่วยแบ่งแผนให้
      </p>
      <textarea
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="เช่น สอบชีวะอีก 10 วัน มี 6 บท ยังไม่ได้อ่านเลย"
        rows={3}
        className="sm-input w-full px-3 py-2 rounded-xl font-body text-sm resize-none"
        style={{ ...glass({ alpha: 0.10 }), color: C.text }}
      />
      <button
        onClick={ask}
        disabled={loading || !input.trim()}
        className="sm-btn w-full py-2.5 rounded-xl font-body text-sm flex items-center justify-center gap-2"
        style={{ ...glassTint(C.violet, 0.28, 18), color: C.text, opacity: loading || !input.trim() ? 0.6 : 1 }}
      >
        {loading ? (<><Loader2 size={16} className="animate-spin" /> กำลังวางแผน...</>) : 'สร้างแผนอ่าน'}
      </button>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-xl" style={glassTint(C.coral, 0.14, 16)}>
          <AlertCircle size={16} style={{ color: C.coral }} />
          <p className="font-body text-xs" style={{ color: C.text }}>{error}</p>
        </div>
      )}

      {result && (
        <div className="sm-pop-anim p-4 rounded-2xl" style={glass({ alpha: 0.12 })}>
          <p className="font-body text-sm" style={{ color: C.text }}>{result.subject} · เหลือ {result.totalDays} วัน</p>
          <div className="mt-3 divide-y" style={{ borderColor: C.border }}>
            {(result.plan || []).map((step, i) => (
              <div key={i} className="py-2">
                <p className="font-body text-xs" style={{ color: C.textMuted }}>{step.date_label}</p>
                <p className="font-body text-sm mt-0.5" style={{ color: C.text }}>{step.task}</p>
              </div>
            ))}
          </div>
          <button
            onClick={handleSave}
            disabled={saved}
            className="sm-btn mt-3 w-full py-2 rounded-xl font-body text-xs"
            style={{ border: `1px solid ${C.border}`, color: saved ? C.mint : C.text }}
          >
            {saved ? 'บันทึกลงแผนอ่านแล้ว' : 'บันทึกลงแผนอ่าน'}
          </button>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Root app                                                              */
/* ------------------------------------------------------------------ */
export default function StudyMateApp() {
  const [data, setData] = useState(null);
  const [tab, setTab] = useState('dashboard');
  const [aiOpen, setAiOpen] = useState(false);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY, false);
        setData(res && res.value ? JSON.parse(res.value) : emptyData());
      } catch (e) {
        setData(emptyData());
      }
    })();
  }, []);

  function showToast(msg) {
    setToast(msg);
    setTimeout(() => setToast(null), 2200);
  }

  async function persist(next) {
    setData(next);
    try {
      const ok = await window.storage.set(STORAGE_KEY, JSON.stringify(next), false);
      if (!ok) showToast('บันทึกไม่สำเร็จ');
    } catch (e) {
      console.error(e);
      showToast('บันทึกไม่สำเร็จ ลองใหม่อีกครั้ง');
    }
  }

  const addSubject = (name) => {
    const color = PALETTE[data.subjects.length % PALETTE.length];
    persist({ ...data, subjects: [...data.subjects, { id: uid(), name: name.trim(), color }] });
  };
  const deleteSubject = (id) => persist({ ...data, subjects: data.subjects.filter((s) => s.id !== id) });
  const addExam = (exam) => persist({ ...data, exams: [...data.exams, { id: uid(), chaptersDone: 0, ...exam }] });
  const updateExam = (id, patch) => persist({ ...data, exams: data.exams.map((e) => (e.id === id ? { ...e, ...patch } : e)) });
  const deleteExam = (id) => persist({ ...data, exams: data.exams.filter((e) => e.id !== id) });
  const addHomework = (hw) => persist({ ...data, homework: [...data.homework, { id: uid(), done: false, ...hw }] });
  const toggleHomework = (id) => persist({ ...data, homework: data.homework.map((h) => (h.id === id ? { ...h, done: !h.done } : h)) });
  const deleteHomework = (id) => persist({ ...data, homework: data.homework.filter((h) => h.id !== id) });
  const logSession = (subjectId, minutes) => persist({ ...data, sessions: [...data.sessions, { id: uid(), subjectId, minutes, date: todayISO() }] });
  const saveAIPlan = (plan) => {
    persist({ ...data, aiPlans: [...data.aiPlans, { id: uid(), ...plan }] });
    showToast('บันทึกแผนแล้ว');
  };
  const deleteAIPlan = (id) => persist({ ...data, aiPlans: data.aiPlans.filter((p) => p.id !== id) });
  const resetAll = () => {
    persist(emptyData());
    showToast('รีเซ็ตข้อมูลแล้ว');
  };

  if (data === null) {
    return (
      <div className="min-h-screen flex items-center justify-center relative">
        <style>{styleBlock}</style>
        <LiquidBackdrop />
        <Loader2 className="animate-spin" size={22} style={{ color: C.text }} />
      </div>
    );
  }

  const screenProps = {
    data, addSubject, deleteSubject, addExam, updateExam, deleteExam,
    addHomework, toggleHomework, deleteHomework, logSession,
    saveAIPlan, deleteAIPlan, resetAll, setTab, openAI: () => setAiOpen(true),
  };

  return (
    <div className="min-h-screen font-body flex flex-col md:flex-row relative">
      <style>{styleBlock}</style>
      <LiquidBackdrop />

      <aside className="hidden md:flex md:flex-col md:w-56 md:shrink-0 md:m-4 md:rounded-3xl md:sticky md:top-4 md:h-[calc(100vh-2rem)]" style={glass({ alpha: 0.12, blur: 32 })}>
        <div className="px-5 py-6 flex items-center gap-2">
          <BookOpen size={20} style={{ color: C.text }} />
          <span className="font-display text-lg" style={{ color: C.text }}>StudyMate</span>
        </div>
        <nav className="flex-1 px-3 space-y-1">
          {[...NAV_ITEMS, DESKTOP_EXTRA].map((item) => {
            const Icon = item.icon;
            const active = tab === item.key;
            return (
              <button
                key={item.key}
                onClick={() => setTab(item.key)}
                className="sm-btn w-full flex items-center gap-3 px-3 py-2.5 rounded-2xl font-body text-sm"
                style={active ? { ...glassTint(C.violet, 0.22, 14), color: C.text } : { backgroundColor: 'transparent', color: C.textMuted }}
              >
                <Icon size={17} /> {item.label}
              </button>
            );
          })}
        </nav>
      </aside>

      <main className="flex-1 min-w-0 px-4 md:px-8 py-5 md:py-8 pb-24 md:pb-8 max-w-2xl mx-auto w-full">
        {tab === 'dashboard' && <Dashboard {...screenProps} />}
        {tab === 'planner' && <Planner {...screenProps} />}
        {tab === 'homework' && <Homework {...screenProps} />}
        {tab === 'focus' && <Focus {...screenProps} />}
        {tab === 'stats' && <Stats {...screenProps} />}
        {tab === 'ai' && (
          <div className="space-y-6 pb-4">
            <div>
              <p className="font-body text-sm" style={{ color: C.textMuted }}>ผู้ช่วยวางแผน</p>
              <h1 className="font-display text-2xl mt-0.5" style={{ color: C.text }}>AI ช่วยวางแผนอ่าน</h1>
            </div>
            <AIAssistantPanel saveAIPlan={saveAIPlan} embedded />
          </div>
        )}
      </main>

      <nav className="sm-tab-bar md:hidden fixed bottom-3 left-3 right-3 flex items-center justify-around px-2 py-2 z-40">
        {NAV_ITEMS.map((item) => {
          const Icon = item.icon;
          const active = tab === item.key;
          return (
            <button
              key={item.key}
              onClick={() => setTab(item.key)}
              className={`sm-btn flex flex-col items-center gap-0.5 px-3 py-1.5 rounded-full ${active ? 'sm-tab-active' : ''}`}
            >
              <Icon size={19} style={{ color: active ? C.text : C.textMuted }} />
              <span className="font-body" style={{ color: active ? C.text : C.textMuted, fontSize: '10px' }}>{item.label}</span>
            </button>
          );
        })}
      </nav>

      <button
        aria-label="เปิดผู้ช่วย AI"
        onClick={() => setAiOpen(true)}
        className="sm-btn sm-lift md:hidden fixed bottom-24 right-4 w-13 h-13 rounded-full flex items-center justify-center z-40"
        style={{ ...glassTint(C.violet, 0.3, 20), width: '52px', height: '52px' }}
      >
        <Sparkles size={20} style={{ color: C.text }} />
      </button>

      {aiOpen && (
        <Modal title="ผู้ช่วย AI" onClose={() => setAiOpen(false)}>
          <AIAssistantPanel saveAIPlan={saveAIPlan} embedded />
        </Modal>
      )}

      {toast && (
        <div
          className="sm-pop-anim fixed bottom-24 md:bottom-6 left-1/2 -translate-x-1/2 px-4 py-2 rounded-full font-body text-xs z-50"
          style={{ ...glass({ alpha: 0.16, blur: 24, border: C.borderStrong }), color: C.text }}
        >
          {toast}
        </div>
      )}
    </div>
  );
}
